-- =====================================================================
-- 257 — Lote 1 LNME (3/4): perfis em public.drug_profiles (2/2)
-- ---------------------------------------------------------------------
-- Segunda metade dos perfis (clorpromazina → dapsona). Mesmo método,
-- fontes e padrão 7.6 da migração 256. Idempotente.
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('clorpromazina',
   E'Clorpromazina é um medicamento antipsicótico clássico, usado para tratar surtos psicóticos, agitação intensa e náuseas/vómitos graves. É um dos fármacos mais usados na saúde mental em todo o mundo pela sua eficácia e custo baixo.',
   E'Chlorpromazine is a classic antipsychotic medicine used to treat psychotic episodes, severe agitation and severe nausea/vomiting. It is one of the most widely used mental health drugs worldwide for its efficacy and low cost.',
   E'Fenotiazina dimetilaminopropílica que bloqueia recetores dopaminérgicos D2 (efeito antipsicótico e antiemético), com antagonismo aditivo em recetores muscarínicos (efeitos anticolinérgicos), alfa-1-adrenérgicos (hipotensão) e H1 (sedação). Forte efeito sedativo; risco de prolongamento QT e discinesia tardia com uso crónico. Metabolismo hepático extenso (CYP2D6/1A2), muitos metabolitos; meia-vida 16–30 h.',
   E'Dimethylaminopropyl phenothiazine blocking dopaminergic D2 receptors (antipsychotic and antiemetic effect), with additive antagonism at muscarinic (anticholinergic effects), alpha-1-adrenergic (hypotension) and H1 (sedation) receptors. Strong sedative effect; QT prolongation and tardive dyskinesia risk with chronic use. Extensive hepatic metabolism (CYP2D6/1A2), many metabolites; half-life 16–30 h.',
   E'• Esquizofrenia e outros quadros psicóticos\n• Mania e agitação psicomotora intensa\n• Náuseas e vómitos graves/refratários\n• Solução da agitação pré-anestésica e do soluço intratável (uso adjuvante)',
   E'• Schizophrenia and other psychotic disorders\n• Mania and severe psychomotor agitation\n• Severe/refractory nausea and vomiting\n• Pre-anaesthetic agitation and intractable hiccups (adjuvant use)',
   E'• Sonolência e sedação intensas\n• Hipotensão ortostática, tonturas\n• Boca seca, obstipação, visão turva, retenção urinária\n• Rigidez, tremores, acatisia (sintomas extrapiramidais)\n• Prolongamento do QT, fotossensibilidade cutânea\n• Discinesia tardia (uso crónico) e síndrome neuroléptica maligna (raro, grave)\n• Procure ajuda imediata se houver febre alta com rigidez muscular, confusão ou desmaio.',
   E'• Intense drowsiness and sedation\n• Orthostatic hypotension, dizziness\n• Dry mouth, constipation, blurred vision, urinary retention\n• Rigidity, tremor, akathisia (extrapyramidal symptoms)\n• QT prolongation, skin photosensitivity\n• Tardive dyskinesia (chronic use) and neuroleptic malignant syndrome (rare, serious)\n• Seek immediate help if there is high fever with muscle rigidity, confusion or fainting.',
   E'• Reduzir dose em idosos (risco de hipotensão e delirium)\n• Evitar em doença de Parkinson, glaucoma de ângulo fechado e mielossupressão\n• Precaução com outros fármacos que prolongam o QT\n• Proteção solar e evitar álcool; never stop abruptly after long use',
   E'• Reduce dose in the elderly (hypotension and delirium risk)\n• Avoid in Parkinson disease, narrow-angle glaucoma and myelosuppression\n• Caution with other QT-prolonging drugs\n• Sun protection and avoid alcohol; never stop abruptly after long use',
   E'Rótulo aprovado DailyMed/FDA — Chlorpromazine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d43718e5-66d7-44f9-9fc8-80d38d3e41ce — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Chlorpromazine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d43718e5-66d7-44f9-9fc8-80d38d3e41ce — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('prometazina',
   E'Prometazina é um anti-histamínico sedativo usado para alergias intensas, náuseas/vómitos e insónia ocasional. Também é usado antes e após cirurgias para acalmar e prevenir vómitos. Pode dar muito sono.',
   E'Promethazine is a sedating antihistamine used for intense allergies, nausea/vomiting and occasional insomnia. It is also used before and after surgery to calm patients and prevent vomiting. It can cause significant drowsiness.',
   E'Fenotiazina sem ação antipsicótica relevante: antagonista potente H1 (sedação forte), com efeitos anticolinérgicos, antiemético (D2 no centro do vómito) e sedativo. Início 20–30 min (oral/IM), duração 4–12 h; metabolismo hepático extenso, meia-vida 10–19 h. Risco de depressão respiratória em < 2 anos (contraindicado) e necrose tecidual com extravasação IV.',
   E'Phenothiazine without relevant antipsychotic action: potent H1 antagonist (strong sedation), with anticholinergic effects, antiemetic (D2 in the vomiting centre) and sedative. Onset 20–30 min (oral/IM), duration 4–12 h; extensive hepatic metabolism, half-life 10–19 h. Respiratory depression risk under 2 years (contraindicated) and tissue necrosis with IV extravasation.',
   E'• Reações alérgicas (rinite, urticária; tratamento adjuvante da anafilaxia)\n• Náuseas e vómitos (incluindo pós-operatórios e cinetose)\n• Sedação pré e pós-operatória\n• Insónia ocasional (uso de curto prazo)',
   E'• Allergic reactions (rhinitis, urticaria; anaphylaxis adjunct treatment)\n• Nausea and vomiting (including postoperative and motion sickness)\n• Pre- and postoperative sedation\n• Occasional insomnia (short-term use)',
   E'• Sonolência intensa, ressaca medicamentosa\n• Boca seca, visão turva, obstipação, retenção urinária\n• Tonturas, hipotensão\n• Agitação paradoxal (crianças e idosos)\n• Reações extrapiramidais (raro)\n• Necrose tecidual com extravasamento IV\n• Procure ajuda imediata se houver dificuldade em respirar (especialmente em crianças) ou sinais de necrose no local da injeção.',
   E'• Intense drowsiness, drug hangover\n• Dry mouth, blurred vision, constipation, urinary retention\n• Dizziness, hypotension\n• Paradoxical agitation (children and the elderly)\n• Extrapyramidal reactions (rare)\n• Tissue necrosis with IV extravasation\n• Seek immediate help if there is breathing difficulty (especially in children) or signs of necrosis at the injection site.',
   E'• CONTRAINDICADA em crianças < 2 anos (morte súbita por depressão respiratória)\n• Não injetar por via arterial (gangrena); preferir via IM profunda em opção oral inviável\n• Reduzir dose em idosos; precaução em retencão urinária e glaucoma\n• Não associar a opioides/ benzodiazepinas sem redução de dose (sedação aditiva)',
   E'• CONTRAINDICATED in children < 2 years (sudden death from respiratory depression)\n• Do not inject intra-arterially (gangrene); prefer deep IM when oral is not feasible\n• Reduce dose in the elderly; caution in urinary retention and glaucoma\n• Do not combine with opioids/benzodiazepines without dose reduction (additive sedation)',
   E'Rótulo aprovado DailyMed/FDA — Promethazine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51e3baab-eba7-460c-9de1-bf6cfc378310 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Promethazine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51e3baab-eba7-460c-9de1-bf6cfc378310 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('hidroxizina',
   E'Hidroxizina é um anti-histamínico com efeito calmante, usado para ansiedade tensa, prurido intenso (alergias, urticária) e sedação leve antes de procedimentos. Não causa dependência, ao contrário dos ansiolíticos tradicionais.',
   E'Hydroxyzine is an antihistamine with a calming effect, used for tension anxiety, intense itching (allergies, urticaria) and light sedation before procedures. Unlike traditional anxiolytics, it does not cause dependence.',
   E'Antagonista H1 de 1.ª geração (piperazina) com marcada ação sedativa, ansiolítica e antipruriginosa central; sem propriedades antipsicóticas nem aditivas. Início 15–60 min (oral), duração 4–6 h; metabolismo hepático (CYP3A4/2D6) a cetotifeno (metabolito ativo parcial), meia-vida ~20 h (adultos). Prolongamento QT dose-dependente documentado.',
   E'First-generation H1 antagonist (piperazine) with marked central sedative, anxiolytic and antipruritic action; no antipsychotic or addictive properties. Onset 15–60 min (oral), duration 4–6 h; hepatic metabolism (CYP3A4/2D6) to cetirizine (partially active metabolite), half-life ~20 h (adults). Documented dose-dependent QT prolongation.',
   E'• Ansiedade e tensão (aguda e crónica, em adultos e crianças)\n• Prurido por alergias, urticária e histaminose\n• Sedação pré-operatória e pré-procedimento\n• Insónia ocasional (adjuvante)',
   E'• Anxiety and tension (acute and chronic, in adults and children)\n• Itching from allergies, urticaria and histamine release\n• Preoperative and pre-procedure sedation\n• Occasional insomnia (adjuvant)',
   E'• Sonolência e boca seca (as mais comuns)\n• Tonturas, cefaleias\n• Visão turva, obstipação, retenção urinária\n• Agitação paradoxal em crianças (raro)\n• Prolongamento do QT (doses altas)\n• Procure ajuda imediata se houver palpitações, desmaio ou dificuldade em urinar.',
   E'• Drowsiness and dry mouth (the most common)\n• Dizziness, headache\n• Blurred vision, constipation, urinary retention\n• Paradoxical agitation in children (rare)\n• QT prolongation (high doses)\n• Seek immediate help if there are palpitations, fainting or trouble urinating.',
   E'• Reduzir dose em idosos (delirium, QT)\n• Precaução com outros fármacos que prolongam o QT (antidepressivos, macrólidos, antiarrítmicos)\n• Evitar na gravidez precoce e amamentação\n• Precaução em glaucoma, hipertrofia prostática e obstipação crónica',
   E'• Reduce dose in the elderly (delirium, QT)\n• Caution with other QT-prolonging drugs (antidepressants, macrolides, antiarrhythmics)\n• Avoid in early pregnancy and breastfeeding\n• Caution in glaucoma, prostatic hypertrophy and chronic constipation',
   E'Rótulo aprovado DailyMed/FDA — Hydroxyzine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=58d99cf6-2319-410b-b8be-de9c304541b6 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Hydroxyzine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=58d99cf6-2319-410b-b8be-de9c304541b6 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('imipramina',
   E'Imipramina é um antidepressivo tricíclico clássico. Para além da depressão, é usado na enurese noturna (xixi na cama) em crianças e na dor neuropática crónica. Tende a causar mais efeitos secundários que os antidepressivos modernos.',
   E'Imipramine is a classic tricyclic antidepressant. Besides depression, it is used for nocturnal enuresis (bedwetting) in children and chronic neuropathic pain. It tends to cause more side effects than modern antidepressants.',
   E'Antidepressivo tricíclico terciário que inibe a recaptação de serotonina e noradrenalina, com antagonismo potente em recetores muscarínicos, H1, alfa-1-adrenérgicos e prolongamento do QT. Metabolismo hepático (CYP2D6/1A2/2C19) a desipramina (metabolito ativo mais noradrenérgico); meia-vida 6–20 h. Índice terapêutico estreito — toxicidade cardíaca potencialmente fatal em sobredosagem.',
   E'Tertiary tricyclic antidepressant inhibiting serotonin and noradrenaline reuptake, with potent antagonism at muscarinic, H1, alpha-1-adrenergic receptors and QT prolongation. Hepatic metabolism (CYP2D6/1A2/2C19) to desipramine (more noradrenergic active metabolite); half-life 6–20 h. Narrow therapeutic index — potentially fatal cardiac toxicity in overdose.',
   E'• Depressão major (resistente ou quando ISRS não são adequados)\n• Enurese noturna em crianças (> 6 anos, após exclusão de causas orgânicas)\n• Dor neuropática crónica (adjuvante)\n• Transtorno de pânico (indicação clássica)',
   E'• Major depression (resistant or when SSRIs are unsuitable)\n• Nocturnal enuresis in children (> 6 years, after excluding organic causes)\n• Chronic neuropathic pain (adjuvant)\n• Panic disorder (classic indication)',
   E'• Boca seca, obstipação, visão turva, retenção urinária (anticolinérgicos)\n• Sonolência ou agitação, tremor fino\n• Ganho ponderal, hipotensão ortostática\n• Taquicardia, prolongamento do QT, arritmias\n• Disfunção sexual\n• Convulsões (reduz o limiar)\n• Procure ajuda imediata em caso de sobredosagem (mesmo pequena): arritmias potencialmente fatais. Sinais de alerta: palpitações, desmaio, confusão grave, retenção urinária completa.',
   E'• Dry mouth, constipation, blurred vision, urinary retention (anticholinergic)\n• Drowsiness or agitation, fine tremor\n• Weight gain, orthostatic hypotension\n• Tachycardia, QT prolongation, arrhythmias\n• Sexual dysfunction\n• Seizures (lowers the threshold)\n• Seek immediate help in case of overdose (even small): potentially fatal arrhythmias. Red flags: palpitations, fainting, severe confusion, complete urinary retention.',
   E'• CUIDADO EXTRA em risco de suicídio (toxicidade em sobredosagem muito superior aos ISRS)\n• ECG basal e em casos de risco (cardiopatia, idosos, doses altas)\n• Não associar a IMAO; precaução com outros prolongadores do QT\n• Titular lento; não parar abruptamente após uso prolongado (síndrome de suspensão)',
   E'• EXTRA CARE with suicide risk (overdose toxicity far greater than SSRIs)\n• Baseline ECG and in at-risk cases (heart disease, elderly, high doses)\n• Do not combine with MAOIs; caution with other QT-prolonging drugs\n• Slow titration; do not stop abruptly after prolonged use (withdrawal syndrome)',
   E'Rótulo aprovado DailyMed/FDA — Imipramine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=649837df-147f-436c-9553-32ffecf4c6f1 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Imipramine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=649837df-147f-436c-9553-32ffecf4c6f1 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('clotrimazol',
   E'Clotrimazol é um antifúngico de uso local (creme, solução, ovulos) contra micoses da pele, pregas e zona genital/vulvovaginal. Atua diretamente no fungo, raramente com efeitos no resto do corpo.',
   E'Clotrimazole is a topical antifungal (cream, solution, pessaries) against skin, fold and genital/vulvovaginal fungal infections. It acts directly on the fungus, rarely affecting the rest of the body.',
   E'Imidazólico de uso tópico que inibe a 14-α-desmetilase do CYP51 fúngico, bloqueando a síntese de ergosterol da membrana celular do fungo — efeito fungistático em doses terapêuticas, fungicida com exposição prolongada. Absorção sistémica mínima (< 0,5% cutâneo; ~3–10% vaginal), pelo que interações sistémicas são irrelevantes. Metabolitos inativos excretados hepaticamente.',
   E'Topical imidazole inhibiting fungal CYP51 14-α-demethylase, blocking ergosterol synthesis in the fungal cell membrane — fungistatic at therapeutic doses, fungicidal with prolonged exposure. Minimal systemic absorption (< 0.5% cutaneous; ~3–10% vaginal), so systemic interactions are irrelevant. Inactive metabolites excreted hepatically.',
   E'• Tineas cutâneas (pé de atleta, tinha inguinal, tinha corporal)\n• Candidíase cutânea e vulvovaginal\n• Pitiríase versicolor\n• Eritrasma (adjuvante)',
   E'• Cutaneous tineas (athlete''s foot, jock itch, tinea corporis)\n• Cutaneous and vulvovaginal candidiasis\n• Pityriasis versicolor\n• Erythrasma (adjuvant)',
   E'• Irritação local, ardor, vermelhidão transitórias\n• Reação alérgica local (raro)\n• Irritação do parceiro sexual (na candidíase vaginal, com preservativos — risco de lesão do látex)\n• Procure ajuda se houver dor intensa, inchaço facial/garganta ou piora marcada da lesão.',
   E'• Transient local irritation, burning, redness\n• Local allergic reaction (rare)\n• Partner irritation (in vaginal candidiasis, with condoms — latex damage risk)\n• Seek help if there is intense pain, face/throat swelling or marked worsening of the lesion.',
   E'• Uso exclusivamente externo; não ingerir nem aplicar nos olhos\n• Continuar o tratamento 1–2 semanas após a resolução visível (prevenir recaída)\n• Na candidíase vaginal, considerar tratamento do parceiro em casos recorrentes\n• Precaução no 1.º trimestre da gravidez (uso vaginal — avaliar benefício/risco)',
   E'• External use only; do not swallow or apply to the eyes\n• Continue treatment 1–2 weeks after visible resolution (prevent relapse)\n• In vaginal candidiasis, consider partner treatment in recurrent cases\n• Caution in the 1st trimester of pregnancy (vaginal use — weigh benefit/risk)',
   E'Rótulo aprovado DailyMed/FDA — Clotrimazole Cream: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4581d0c9-1f85-42c8-87d7-5f38fbbc923a — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Clotrimazole Cream: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4581d0c9-1f85-42c8-87d7-5f38fbbc923a — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('miconazol',
   E'Miconazol é um antifúngico de uso local (cremes, soluções, ovulos, gel oral) contra micoses da pele, pregas, zona genital e, no caso do gel, candidíase da boca. É amplamente disponível e bem tolerado.',
   E'Miconazole is a topical antifungal (creams, solutions, pessaries, oral gel) against skin, fold and genital fungal infections and, in gel form, oral candidiasis. It is widely available and well tolerated.',
   E'Imidazólico tópico que bloqueia a síntese de ergosterol fúngico (inibição da 14-α-desmetilase) e, em concentrações altas, lesiona diretamente a membrana (fungicida). Absorção sistémica mínima por via cutânea/vaginal; no entanto o gel bucal pode absorver-se o suficiente para interagir com anticoagulantes cumarínicos (inibição CYP2C9) — hemorragias descritas. Metabolismo hepático de fração absorvida.',
   E'Topical imidazole blocking fungal ergosterol synthesis (14-α-demethylase inhibition) and, at high concentrations, directly damaging the membrane (fungicidal). Minimal systemic absorption via skin/vagina; however buccal gel can absorb enough to interact with coumarin anticoagulants (CYP2C9 inhibition) — described haemorrhages. Hepatic metabolism of the absorbed fraction.',
   E'• Tineas cutâneas e pitiríase versicolor\n• Candidíase cutânea, vulvovaginal e oral (gel)\n• Dermatite periorificial por Candida\n• Infecções mistas fungo+bactérias (adjuvante)',
   E'• Cutaneous tineas and pityriasis versicolor\n• Cutaneous, vulvovaginal and oral candidiasis (gel)\n• Periorificial Candida dermatitis\n• Mixed fungal+bacterial infections (adjuvant)',
   E'• Irritação local, ardor, prurido transitórios\n• Reação alérgica local (raro)\n• No gel oral: náuseas, alteração do gosto; com warfarina — risco de hemorragia (interação sistémica)\n• Procure ajuda se houver sinais de hemorragia (hematomas, sangue nas fezes) enquanto usa gel oral com anticoagulante.',
   E'• Transient local irritation, burning, itching\n• Local allergic reaction (rare)\n• With oral gel: nausea, taste change; with warfarin — bleeding risk (systemic interaction)\n• Seek help if there are signs of bleeding (bruising, blood in stool) while using oral gel with an anticoagulant.',
   E'• Uso externo; gel oral não engolir de imediato (manter na boca)\n• ALERTA: gel oral + warfarina/acenocumarol → monitorizar INR com frequência\n• Continuar 1–2 semanas após resolução clínica\n• Gravidez: uso vaginal aceitável após 1.º trimestre; avaliar no 1.º',
   E'• External use; oral gel should not be swallowed immediately (hold in mouth)\n• ALERT: oral gel + warfarin/acenocoumarol → monitor INR frequently\n• Continue 1–2 weeks after clinical resolution\n• Pregnancy: vaginal use acceptable after the 1st trimester; assess in the 1st',
   E'Rótulo DailyMed/FDA — MICONAZOLE 3 Combination Pack (Monistat 3, Insight Pharmaceuticals): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=65c99592-7c11-41fc-8296-aad0a8f39926 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA label — MICONAZOLE 3 Combination Pack (Monistat 3, Insight Pharmaceuticals): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=65c99592-7c11-41fc-8296-aad0a8f39926 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('terbinafina',
   E'Terbinafina é um antifúngico por via oral ou creme que elimina fungos da pele e das unhas. O tratamento oral de unhas é longo (semanas a meses), mas tem taxas de cura altas.',
   E'Terbinafine is an antifungal taken by mouth or as a cream that clears skin and nail fungi. Oral nail treatment is long (weeks to months), but has high cure rates.',
   E'Alilamina que inibe seletivamente a esqualeno epoxidase fúngica, acumulando esqualeno e bloqueando a síntese de ergosterol — fungicida para dermatófitos. Boa absorção oral (> 70%, aumenta com comida), alta lipofilia e ligação a queratina/tecido ungueal (difusão pelo leito ungueal persiste após suspender). Metabolismo hepático extenso (CYP2C9/1A2/3A4), meia-vida de eliminação ~400 h (reatribuição do depósito tecidual); excreção renal de metabolitos.',
   E'Allylamine selectively inhibiting fungal squalene epoxidase, accumulating squalene and blocking ergosterol synthesis — fungicidal for dermatophytes. Good oral absorption (> 70%, increased by food), high lipophilia and keratin/nail-tissue binding (diffusion through the nail bed persists after stopping). Extensive hepatic metabolism (CYP2C9/1A2/3A4), elimination half-life ~400 h (redistribution from tissue depot); renal excretion of metabolites.',
   E'• Onicomicose (fungo das unhas) por dermatófitos — indicação principal oral\n• Tineas cutâneas extensas ou recorrentes (pé de atleta, tinha corporal)\n• Tinha do couro cabeludo (crianças, adjuvante)\n• Micoses cutâneas limitadas (formulação tópica)',
   E'• Onychomycosis (nail fungus) due to dermatophytes — main oral indication\n• Extensive or recurrent cutaneous tineas (athlete''s foot, tinea corporis)\n• Tinea capitis (children, adjuvant)\n• Limited skin mycoses (topical formulation)',
   E'• Cefaleias, tonturas, alterações do gosto (ageusia — por vezes prolongada)\n• Náuseas, dor abdominal, flatulência, diarreia leve\n• Erupção cutânea, urticária\n• Elevação das transaminases (1–3%; raramente hepatite)\n• Neutropenia, lupus induzido, distúrbios do paladar persistentes (raro)\n• Procure ajuda imediata se houver icterícia, urina escura, fadiga intensa ou ulcerações na boca.',
   E'• Headache, dizziness, taste changes (ageusia — sometimes prolonged)\n• Nausea, abdominal pain, flatulence, mild diarrhoea\n• Rash, urticaria\n• Transaminase elevation (1–3%; rarely hepatitis)\n• Neutropenia, drug-induced lupus, persistent taste disorders (rare)\n• Seek immediate help if there is jaundice, dark urine, intense fatigue or mouth ulcers.',
   E'• Avaliar enzimas hepáticas basais em tratamento prolongado; suspender se ALT > 2–3× LSN\n• Reduzir dose na insuficiência renal/hepática crónica\n• Confirmar diagnóstico micológico antes do tratamento oral de unhas (evitar tratar colonização)\n• Não usar oral na gravidez; contracepção durante e 1 mês após',
   E'• Assess baseline liver enzymes in prolonged treatment; stop if ALT > 2–3× ULN\n• Reduce dose in chronic renal/hepatic impairment\n• Confirm mycological diagnosis before oral nail treatment (avoid treating colonisation)\n• Do not use oral form in pregnancy; contraception during and 1 month after',
   E'Rótulo aprovado DailyMed/FDA — Terbinafine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=584d1fae-0120-49a0-e063-6394a90a36fc — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Terbinafine Hydrochloride Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=584d1fae-0120-49a0-e063-6394a90a36fc — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('griseofulvina',
   E'Griseofulvina é um antifúngico oral clássico para tinhas do cabelo, pele e unhas, sobretudo em crianças. Retirou-se em vários países mas continua em uso em muitos programas de saúde pública. Dose por peso; tomar com refeição gordurosa.',
   E'Griseofulvin is a classic oral antifungal for hair, skin and nail tineas, especially in children. It has been withdrawn in some countries but remains in use in many public health programmes. Weight-based dosing; take with a fatty meal.',
   E'Antibiótico fúngico (Penicillium griseofulvum) que perturba o fuso mitótico do fungo por ligação à tubulina — fungistático, requer queratinização nova para incorporar o fármaco e «crescer fora» da infecção. Absorção muito variável (partículas ultramicroinizadas dobram a biodisponibilidade), muito aumentada por refeição gordurosa; meia-vida 9–21 h, induz CYP3A4 e CYP2C9 (interações relevantes com warfarina e contraceptivos orais).',
   E'Fungal antibiotic (Penicillium griseofulvum) disrupting the fungal mitotic spindle by tubulin binding — fungistatic, requires new keratinisation to incorporate the drug and grow out the infection. Very variable absorption (ultramicrosized particles double bioavailability), greatly increased by fatty meal; half-life 9–21 h, induces CYP3A4 and CYP2C9 (relevant interactions with warfarin and oral contraceptives).',
   E'• Tinha do couro cabeludo (tinea capitis) — indicação clássica pediátrica\n• Tinhas cutâneas extensas quando terbinafina não está disponível\n• Onicomicose por dermatófitos (alternativa histórica; cursos longos)',
   E'• Tinea capitis (scalp ringworm) — classic paediatric indication\n• Extensive cutaneous tineas when terbinafine is unavailable\n• Dermatophyte onychomycosis (historical alternative; long courses)',
   E'• Cefaleias (comum), tonturas\n• Náuseas, vómitos, diarreia\n• Fotossensibilidade cutânea\n• Erupção e urticária\n• Leucopenia e elevação de transaminases (raro)\n• Confusão, neuropatia periférica (raro)\n• Procure ajuda imediata se houver icterícia, febre com dor de garganta ou hematomas fáceis.',
   E'• Headache (common), dizziness\n• Nausea, vomiting, diarrhoea\n• Skin photosensitivity\n• Rash and urticaria\n• Leukopenia and transaminase elevation (rare)\n• Confusion, peripheral neuropathy (rare)\n• Seek immediate help if there is jaundice, fever with sore throat or easy bruising.',
   E'• CONTRAINDICADA na gravidez, pré-gravidez (homens e mulheres: contracepção durante e 1 mês após) e porfiria\n• Induz enzimas: reduz eficácia de contraceptivos orais — recomendar método de barreira\n• Monitorizar hemograma em cursos longos\n• Tomar sempre com refeição gordurosa para absorção fiável',
   E'• CONTRAINDICATED in pregnancy, pre-pregnancy (men and women: contraception during and 1 month after) and porphyria\n• Enzyme inducer: reduces oral contraceptive efficacy — recommend barrier method\n• Monitor blood count in long courses\n• Always take with a fatty meal for reliable absorption',
   E'Rótulo aprovado DailyMed/FDA — Griseofulvin Tablet (ultramicrosize): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f21314eb-3581-4e06-9fe7-8239cc80ba11 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Griseofulvin Tablet (ultramicrosize): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f21314eb-3581-4e06-9fe7-8239cc80ba11 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('retinol',
   E'Retinol (vitamina A) é um suplemento essencial para a visão, o sistema imunitário e a pele. Em Angola, a suplementação periódica em crianças é uma estratégia nacional de saúde pública contra a deficiência de vitamina A.',
   E'Retinol (vitamin A) is an essential supplement for vision, the immune system and skin. In Angola, periodic supplementation in children is a national public health strategy against vitamin A deficiency.',
   E'Vitamina lipossolúvel e hormona nuclear (ligandos RAR/RXR) essencial para a diferenciação epitelial, fototransdução (11-cis-retinal) e resposta imune. Armazenada hepático (90% das reservas); absorção intestinal requer bile e gordura (transporte em quilomicrons); estearato/palmitato hidrolisados na mucosa. Hipervitaminose por excesso crónico (hepatotoxicidade, teratogenicidade > 10 000 UI/dia em gravidez).',
   E'Fat-soluble vitamin and nuclear hormone (RAR/RXR ligand) essential for epithelial differentiation, phototransduction (11-cis-retinal) and immune response. Stored in the liver (90% of reserves); intestinal absorption requires bile and fat (chylomicron transport); esters hydrolysed in the mucosa. Hypervitaminosis from chronic excess (hepatotoxicity, teratogenicity > 10 000 IU/day in pregnancy).',
   E'• Deficiência de vitamina A (xeroftalmia, cegueira noturna)\n• Suplementação profilática em crianças 6–59 meses (programa nacional de Angola e da OMS)\n• Suporte nutricional em sarampo (reduz mortalidade) e desnutrição aguda grave\n• Deficiência em doenças de má absorção',
   E'• Vitamin A deficiency (xerophthalmia, night blindness)\n• Prophylactic supplementation in children 6–59 months (Angola national and WHO programme)\n• Nutritional support in measles (reduces mortality) and severe acute malnutrition\n• Deficiency in malabsorption diseases',
   E'• Náuseas, cefaleias, irritabilidade (doses altas agudas)\n• Hepatotoxicidade, dor óssea, alopecia (hipervitaminose crónica)\n• Aumento da pressão intracraniana (pseudotumor cerebral)\n• Teratogenicidade (doses altas na gravidez)\n• Procure ajuda imediata se houver vómitos persistentes e dor de cabeça intensa após dose alta (risco de sobredosagem aguda).',
   E'• Nausea, headache, irritability (acute high doses)\n• Hepatotoxicity, bone pain, alopecia (chronic hypervitaminosis)\n• Raised intracranial pressure (pseudotumour cerebri)\n• Teratogenicity (high doses in pregnancy)\n• Seek immediate help if there are persistent vomiting and intense headache after a high dose (acute overdose risk).',
   E'• RESPEITAR esquema por idade do programa nacional (50 000–200 000 UI, 6–12 mensais, com calendário vacinal)\n• CONTRAINDICADO em doses altas na gravidez; contracepção em mulheres em idade fértil sob tratamento\n• Interage com retinóides sistémicos (isotretinoína, acitretina) — toxicidade aditiva\n• Cuidado com suplementos múltiplos (somatório de vitamina A)',
   E'• RESPECT the national programme age schedule (50 000–200 000 IU, 6–12 monthly, with vaccination calendar)\n• CONTRAINDICATED at high doses in pregnancy; contraception in women of childbearing age on treatment\n• Interacts with systemic retinoids (isotretinoin, acitretin) — additive toxicity\n• Care with multivitamins (vitamin A summation)',
   E'Rótulo DailyMed/FDA — AQUASOL A PARENTERAL (Retinyl Palmitate) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1abd66eb-6ac8-4a9e-a609-251e46ea1a27 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA label — AQUASOL A PARENTERAL (Retinyl Palmitate) Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1abd66eb-6ac8-4a9e-a609-251e46ea1a27 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('tiamina',
   E'Tiamina (vitamina B1) é uma vitamina essencial para o funcionamento dos nervos, músculos e coração. A deficiência (beribéri) e a forma grave (encefalopatia de Wernicke) tratam-se com injeções ou comprimidos de tiamina.',
   E'Thiamine (vitamin B1) is an essential vitamin for nerve, muscle and heart function. Deficiency (beriberi) and the severe form (Wernicke encephalopathy) are treated with thiamine injections or tablets.',
   E'Cofactor enzimático indispensável (na forma pirofosfato de tiamina/TPP) do metabolismo glucídico: complexos de piruvato desidrogenase, α-cetoglutarato desidrogenase e transcetolase das pentoses, além da acetilcolina e condução nervosa. Absorção intestinal por transportadores saturáveis (melhor em doses fracionadas); reservas corporais de 2–3 semanas apenas — deficiência rápida em alcoolismo, hiperémese ou nutrição parentérica sem suplemento. Meia-vida 10–20 dias (TPP); excreção renal de excesso.',
   E'Indispensable enzymatic cofactor (as thiamine pyrophosphate/TPP) of glucose metabolism: pyruvate dehydrogenase, α-ketoglutarate dehydrogenase and pentose transketolase complexes, plus acetylcholine synthesis and nerve conduction. Intestinal absorption via saturable carriers (best in divided doses); body stores last only 2–3 weeks — rapid deficiency in alcoholism, hyperemesis or unsupplemented parenteral nutrition. Half-life 10–20 days (TPP); renal excretion of excess.',
   E'• Encefalopatia de Wernicke (urgência médica: tiamina IV/IM ANTES da glicose)\n• Beribéri húmido (insuficiência cardíaca de alto débito) e seco (neuropatia)\n• Profilaxia em alcoolismo, dieta pobre, hiperémese gravídica e nutrição parentérica\n• Acidose láctica por deficiência de tiamina',
   E'• Wernicke encephalopathy (medical emergency: IV/IM thiamine BEFORE glucose)\n• Wet beriberi (high-output heart failure) and dry beriberi (neuropathy)\n• Prophylaxis in alcoholism, poor diet, hyperemesis gravidarum and parenteral nutrition\n• Lactic acidosis from thiamine deficiency',
   E'• Reações de hipersensibilidade após IV (raro; risco de anafilaxia com preparações antigas)\n• Desconforto no local IM\n• Náuseas transitórias com doses orais altas\n• Sem toxicidade conhecida por excesso oral (excreção renal rápida)\n• Procure ajuda imediata se houver urticária generalizada, dificuldade em respirar ou desmaio após injeção.',
   E'• Hypersensitivity reactions after IV (rare; anaphylaxis risk with older preparations)\n• Discomfort at the IM site\n• Transient nausea with high oral doses\n• No known toxicity from oral excess (rapid renal excretion)\n• Seek immediate help if there is generalised urticaria, trouble breathing or fainting after injection.',
   E'• REGRAS DE OURO: dar tiamina ANTES de qualquer perfusão de glicose em doentes em risco (Wernicke iatrogénica)\n• IV apenas com preparações modernas e diluição adequada; IM é via segura e habitual\n• Doses orais altas: dividir (absorção saturável)\n• Alcoólicos: sempre multivitaminas + tiamina; monitorizar melhoria neurológica',
   E'• GOLDEN RULES: give thiamine BEFORE any glucose infusion in at-risk patients (iatrogenic Wernicke)\n• IV only with modern preparations and proper dilution; IM is the safe, usual route\n• High oral doses: divide (saturable absorption)\n• Alcoholics: always multivitamins + thiamine; monitor neurological improvement',
   E'Rótulo DailyMed/FDA — THIAMINE HYDROCHLORIDE Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06446e9a-0e85-0623-e063-6294a90ac403 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA label — THIAMINE HYDROCHLORIDE Injection: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06446e9a-0e85-0623-e063-6294a90ac403 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('dapsona',
   E'Dapsona é o antibiótico base do tratamento da lepra (doença de Hansen) e também usado na dermite herpetiforme e, em associação com pirimetamina, na toxoplasmose. Faz parte dos regimes multi-medicamentosos da OMS, gratuitos em programas oficiais.',
   E'Dapsone is the backbone antibiotic of leprosy (Hansen disease) treatment, also used in dermatitis herpetiformis and, combined with pyrimethamine, in toxoplasmosis. It is part of WHO multidrug regimens, free in official programmes.',
   E'Sulfona bacteriostática análoga às sulfonamidas: inibe a dihidropteroato sintase, bloqueando a síntese de folato bacteriano — ativa contra Mycobacterium leprae sensível. Absorção oral quase completa (pico 2–8 h), distribuição ampla, concentração alta na pele e músculos; circulação entero-hepática e meia-vida longa (20–30 h) permitem dose única diária. Metabolismo N-acetilação (acetiladores rápidos/lentos) e hidroxilação (CYP2C9/3A4) — metabolitos hidroxilamina causam metemoglobinemia e hemólise dose-dependente.',
   E'Bacteriostatic sulfone analogous to sulfonamides: inhibits dihydropteroate synthase, blocking bacterial folate synthesis — active against susceptible Mycobacterium leprae. Almost complete oral absorption (peak 2–8 h), wide distribution, high skin and muscle concentrations; enterohepatic circulation and long half-life (20–30 h) allow once-daily dosing. N-acetylation metabolism (fast/slow acetylators) and hydroxylation (CYP2C9/3A4) — hydroxylamine metabolites cause dose-dependent methaemoglobinaemia and haemolysis.',
   E'• Lepra (doença de Hansen) — pilares dos regimes MDT da OMS (com rifampicina e clofazimina)\n• Dermite herpetiforme (doença celíaca cutânea)\n• Toxoplasmose cerebral (alternativa, com pirimetamina e ácido folínico)\n• Pneumocistose (profilaxia alternativa em alérgicos ao cotrimoxazol)',
   E'• Leprosy (Hansen disease) — backbone of WHO MDT regimens (with rifampicin and clofazimine)\n• Dermatitis herpetiformis (cutaneous coeliac disease)\n• Cerebral toxoplasmosis (alternative, with pyrimethamine and folinic acid)\n• Pneumocystosis (prophylaxis alternative in cotrimoxazole-allergic patients)',
   E'• Metemoglobinemia (cianose, fadiga, dispneia — dose-dependente)\n• Hemólise (sobretudo em deficiência de G6PD)\n• Náuseas, vómitos, anorexia\n• Síndrome de hipersensibilidade à dapsona (DRESS: febre, erupção, adenopatias, eosinofilia — 2–8 semanas após início)\n• Neuropatia motora (raro)\n• Reação de reversão tipo 1 na lepra (neurite dolorosa — urgência)\n• Procure ajuda imediata se houver lábios/unhas azulados, urina escura, icterícia, febre com erupção ou dor/parésia nos nervos.',
   E'• Methaemoglobinaemia (cyanosis, fatigue, breathlessness — dose-dependent)\n• Haemolysis (especially in G6PD deficiency)\n• Nausea, vomiting, anorexia\n• Dapsone hypersensitivity syndrome (DRESS: fever, rash, lymphadenopathy, eosinophilia — 2–8 weeks after starting)\n• Motor neuropathy (rare)\n• Type 1 reversal reaction in leprosy (painful neuritis — emergency)\n• Seek immediate help if there are blue lips/nails, dark urine, jaundice, fever with rash or nerve pain/weakness.',
   E'• Triar G6PD antes do início (populações de risco em Angola — hemólise grave)\n• Monitorizar hemograma e metemoglobinemia se sintomático\n• DRESS: suspender IMEDIATAMENTE e não readmitir\n• Suplemento de ácido fólico em gravidez; precaução na amamentação',
   E'• Screen for G6PD before starting (at-risk populations in Angola — severe haemolysis)\n• Monitor blood count and methaemoglobinaemia if symptomatic\n• DRESS: stop IMMEDIATELY and never rechallenge\n• Folic acid supplement in pregnancy; caution in breastfeeding',
   E'Rótulo aprovado DailyMed/FDA — Dapsone Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=839d7440-ba0e-4c56-b648-d374b155cf03 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   E'DailyMed/FDA approved label — Dapsone Tablet: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=839d7440-ba0e-4c56-b648-d374b155cf03 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
       indications_pt, indications_en, side_effects_pt, side_effects_en,
       precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
